return {["fb33_01"]={["down"]=[[fb33_03]],["dsc"]=[[你快步而行，只见迎面黑压压的一座大森林。走近前去，只见左首一排九株大松树参天并列，好像有些异样。]],["fightBackground"]=[[森林外]],["id"]=[[fb33_01]],["name"]=[[黑森林]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb33_02"]={["down"]=[[fb33_06]],["dsc"]=[[你信步而行，举步踏到的尽是矮树长草，这里没有路，每走一步，荆棘都钩刺到小腿，划破你的身体。]],["fightBackground"]=[[森林外]],["id"]=[[fb33_02]],["item1"]=[[fb33item16]],["name"]=[[荆棘林]],["permission"]=2,["role1"]=[[fb33r02_1]],["role2"]=[[fb33r02_2]],["role3"]=[[fb33r02_3]],["role4"]=[[fb33r02_4]],["stepMusic"]=[[jiaobu]]},["fb33_03"]={["down"]=[[fb33_04]],["dsc"]=[[铁索桥共是四条铁索，两条在下，上铺木板，以供行走，两条在旁作为扶手。一踏上桥，几条铁索便即晃动，只要一个失足，卷入江水，任你多好的水性也难活命。]],["fightBackground"]=[[山内]],["id"]=[[fb33_03]],["name"]=[[铁索桥]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb33_01]]},["fb33_04"]={["dsc"]=[[江岸尽是山石，小路也没一条，走出七八里地，见到一株野生桃树，又走了十里，才见到一条小径。沿着小径行去，终于见了铁索桥，只见桥边石上刻着“善人渡”。]],["fightBackground"]=[[山内]],["id"]=[[fb33_04]],["left"]=[[fb33_05]],["name"]=[[江岸]],["permission"]=2,["role1"]=[[fb33r04_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb33_03]]},["fb33_05"]={["dsc"]=[[你一眼望出去，之见前面怒涛汹涌，水流湍急，竟是一条大江。江岸山石壁立，看这情势，已是到了澜沧江畔。江面有十来丈高，但要走到江岸，却也着实不易。]],["fightBackground"]=[[山内]],["id"]=[[fb33_05]],["item1"]=[[bfitem1]],["item2"]=[[ycitem1]],["left"]=[[fb33_06]],["name"]=[[澜沧江畔]],["permission"]=2,["right"]=[[fb33_04]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]]},["fb33_06"]={["down"]=[[fb33_07]],["dsc"]=[[你信步而行，举步踏到的尽是矮树长草，这里没有路，每走一步，荆棘都钩刺到小腿，划破你的身体。]],["fightBackground"]=[[山内]],["id"]=[[fb33_06]],["name"]=[[荆棘林]],["permission"]=2,["right"]=[[fb33_05]],["role1"]=[[fb33r06_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb33_02]]},["fb33_07"]={["down"]=[[fb33_09]],["dsc"]=[[在山路的旁边了出现一条小溪。周围安静极了，南面是一条上山的路，正北面都是荆棘和矮草灌木，走在里面一定会划伤身体，依稀有一条小路通向深处。]],["fightBackground"]=[[山内]],["id"]=[[fb33_07]],["item1"]=[[2019qxhdd1]],["name"]=[[山中小溪]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb33_06]]},["fb33_08"]={["dsc"]=[[你片刻间转过山坳，只见一大堆乱石之中团团坐着二十余人。人丛中一个瘦小的老者坐在一块高岩之上，高出旁人。]],["fightBackground"]=[[山内]],["id"]=[[fb33_08]],["leftDown"]=[[fb33_11]],["name"]=[[乱石堆]],["permission"]=2,["role1"]=[[fb33r08_1]],["role2"]=[[fb33r08_2]],["role3"]=[[fb33r08_3]],["stepMusic"]=[[jiaobu]]},["fb33_09"]={["dsc"]=[[你正走在一条崎岖不平的路上，四周是阴森森的原始老林，不时传来一阵阵的野兽叫声。东边一条山路向上延伸，不知道通向哪里。]],["fightBackground"]=[[山外]],["id"]=[[fb33_09]],["item1"]=[[fb33item20]],["name"]=[[无量山路]],["permission"]=1,["right"]=[[fb33_10]],["stepMusic"]=[[jiaobu]],["up"]=[[fb33_07]]},["fb33_10"]={["dsc"]=[[这是由青石铺成的小路，路面上夹杂着一些泥沙，小路两边长着一些野草，开出来的野花飘着阵阵花香。四周是阴森森的原始老林，不时传来一阵阵的野兽叫声。]],["fightBackground"]=[[山外]],["id"]=[[fb33_10]],["item1"]=[[fb33item1]],["item2"]=[[fb33item1]],["left"]=[[fb33_09]],["name"]=[[青石小路]],["permission"]=1,["right"]=[[fb33_11]],["stepMusic"]=[[jiaobu]]},["fb33_11"]={["down"]=[[fb33_12]],["dsc"]=[[这是由青石铺成的小路，路面上夹杂着一些泥沙，小路两边长着一些野草，开出来的野花飘着阵阵花香。四周是阴森森的原始老林，不时传来一阵阵的野兽叫声。]],["fightBackground"]=[[山外]],["id"]=[[fb33_11]],["item1"]=[[fb33item1]],["item2"]=[[fb33item1]],["left"]=[[fb33_10]],["name"]=[[青石小路]],["permission"]=1,["rightUp"]=[[fb33_08]],["stepMusic"]=[[jiaobu]]},["fb33_12"]={["dsc"]=[[这是由青石砌成的台阶，方方正正，看起来颇为考究，大青石一块一块直铺到大厅，台阶两边还做了栏杆。]],["fightBackground"]=[[山外]],["id"]=[[fb33_12]],["item1"]=[[fb33item1]],["left"]=[[fb33_13]],["name"]=[[青石台阶]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb33_11]]},["fb33_13"]={["down"]=[[fb33_14]],["dsc"]=[[这是由青石砌成的台阶，方方正正，看起来颇为考究，大青石一块一块直铺到大厅，台阶两边还做了栏杆。]],["fightBackground"]=[[山外]],["id"]=[[fb33_13]],["item1"]=[[fb33item2]],["name"]=[[青石台阶]],["permission"]=1,["right"]=[[fb33_12]],["role1"]=[[fb33r13_1]],["role2"]=[[fb33r13_2]],["role3"]=[[fb33item1]],["stepMusic"]=[[jiaobu]]},["fb33_14"]={["down"]=[[fb33_15]],["dsc"]=[[数十年前，棠家先祖在南诏无量山创下「无量山庄」，掌门居住无量山量剑楼。多年前分为东、北、西三庄，每隔五年，三庄庄下弟子便比武斗剑，获胜者入住量剑楼。]],["fightBackground"]=[[擂台]],["id"]=[[fb33_14]],["item1"]=[[fb33item3]],["name"]=[[无量山庄]],["permission"]=1,["role1"]=[[fb33r14_1]],["role2"]=[[fb33r14_2]],["role3"]=[[fb33r14_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb33_13]]},["fb33_15"]={["dsc"]=[[这里是供来无量剑的客人休息之用，一应茶点具备，窗边一溜平放着不少锦凳，墙上挂着几幅山水画，几缕阳光透过窗外的绿荫中直射进来。]],["id"]=[[fb33_15]],["item1"]=[[fb33item1]],["name"]=[[西厅]],["permission"]=1,["right"]=[[fb33_16]],["stepMusic"]=[[jiaobu]],["up"]=[[fb33_14]]},["fb33_16"]={["down"]=[[fb33_19]],["dsc"]=[[你走在一条宽阔的石板路上。这是用一米见方的巨大石板铺设而成的，可以并行十来个人也绝无问题。两侧是参天古柏，直耸入天。路的尽头，就是量剑楼了。]],["id"]=[[fb33_16]],["item1"]=[[fb33item1]],["left"]=[[fb33_15]],["name"]=[[石板路]],["permission"]=1,["right"]=[[fb33_17]],["role1"]=[[fb33r16_1]],["stepMusic"]=[[jiaobu]]},["fb33_17"]={["dsc"]=[[这里是供来无量剑的客人休息之用，一应茶点具备，窗边一溜平放着不少锦凳，墙上挂着几幅山水画，几缕阳光透过窗外的绿荫中直射进来。]],["id"]=[[fb33_17]],["item1"]=[[fb33item12]],["item2"]=[[fb33item1]],["left"]=[[fb33_16]],["name"]=[[东厅]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb33_18"]={["dsc"]=[[这是无量山庄量剑楼的练功房，两边有两个兵器架，十八武器样样俱全，墙角还散放着几个练力的石锤和一些杂物，庄中弟子每天在此练功。]],["fightBackground"]=[[擂台]],["id"]=[[fb33_18]],["left"]=[[fb33_19]],["name"]=[[东练武场]],["permission"]=2,["role1"]=[[fb33r18_1]],["role2"]=[[fb33r18_2]],["role3"]=[[fb33r18_3]],["stepMusic"]=[[jiaobu]]},["fb33_19"]={["down"]=[[fb33_21]],["dsc"]=[[楼内坐着二人，上首是个四十左右的中年道姑，下首是个五十余岁的老者。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb33_19]],["item1"]=[[fb33item21]],["item2"]=[[fb33item5]],["item3"]=[[fb33item23]],["left"]=[[fb33_20]],["name"]=[[量剑楼]],["permission"]=1,["right"]=[[fb33_18]],["stepMusic"]=[[jiaobu]],["up"]=[[fb33_16]]},["fb33_20"]={["dsc"]=[[这是无量山量剑楼的练功房，两边有两个兵器架，十八武器样样俱全，墙角还散放着几个练力的石锤和一些杂物，庄中弟子每天在此练功。]],["fightBackground"]=[[擂台]],["id"]=[[fb33_20]],["name"]=[[西练武场]],["permission"]=2,["right"]=[[fb33_19]],["role1"]=[[fb33r20_1]],["role2"]=[[fb33r20_2]],["role3"]=[[fb33r20_3]],["stepMusic"]=[[jiaobu]]},["fb33_21"]={["down"]=[[fb33_22]],["dsc"]=[[后院乃量剑楼清闲之所，靠墙放着一张长桌子，上面放了些水果，还有一只大水壶。几只青瓷小碗洗得干干净净。北面是一片松林，也是无量山庄的禁地。]],["id"]=[[fb33_21]],["item1"]=[[fb33item100]],["name"]=[[后院]],["permission"]=2,["role1"]=[[fb33r21_100]],["role2"]=[[fb33r21_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb33_19]]},["fb33_22"]={["down"]=[[fb33_23]],["dsc"]=[[你眼前骤然一黑，朦胧中，只见左右前后，到处都是铺天盖地的松树林。你似乎迷失了方向，像没头苍蝇般到处乱闯。]],["fightBackground"]=[[森林内]],["id"]=[[fb33_22]],["name"]=[[大松林]],["permission"]=2,["role1"]=[[fb33item19]],["role2"]=[[fb33item19]],["role3"]=[[fb33item19]],["role4"]=[[fb33item19]],["stepMusic"]=[[jiaobu]],["up"]=[[fb33_21]]},["fb33_23"]={["down"]=[[fb33_24]],["dsc"]=[[你眼前骤然一黑，朦胧中，只见左右前后，到处都是铺天盖地的松树林。你似乎迷失了方向，像没头苍蝇般到处乱闯。]],["fightBackground"]=[[森林内]],["id"]=[[fb33_23]],["left"]=[[fb33_24]],["name"]=[[大松林]],["permission"]=2,["right"]=[[fb33_23]],["role1"]=[[fb33item19]],["role2"]=[[fb33item19]],["role3"]=[[fb33item19]],["role4"]=[[fb33item19]],["stepMusic"]=[[jiaobu]],["up"]=[[fb33_22]]},["fb33_24"]={["down"]=[[fb33_25]],["dsc"]=[[你眼前骤然一黑，朦胧中，只见左右前后，到处都是铺天盖地的松树林。你似乎迷失了方向，像没头苍蝇般到处乱闯。]],["fightBackground"]=[[森林内]],["id"]=[[fb33_24]],["item1"]=[[fb33item7]],["left"]=[[fb33_24]],["name"]=[[大松林]],["permission"]=2,["right"]=[[fb33_23]],["role1"]=[[fb33item19]],["role2"]=[[fb33item19]],["role3"]=[[fb33item19]],["role4"]=[[fb33item19]],["stepMusic"]=[[jiaobu]],["up"]=[[fb33_24]]},["fb33_25"]={["down"]=[[fb33_26]],["dsc"]=[[你眼前骤然一黑，朦胧中，只见左右前后，到处都是铺天盖地的松树林。你似乎迷失了方向，像没头苍蝇般到处乱闯。]],["fightBackground"]=[[森林内]],["id"]=[[fb33_25]],["item1"]=[[fb33item15]],["left"]=[[fb33_23]],["name"]=[[大松林]],["permission"]=2,["right"]=[[fb33_25]],["role1"]=[[fb33item19]],["role2"]=[[fb33item19]],["role3"]=[[fb33item19]],["role4"]=[[fb33item19]],["stepMusic"]=[[jiaobu]],["up"]=[[fb33_26]]},["fb33_26"]={["down"]=[[fb33_22]],["dsc"]=[[你眼前骤然一黑，朦胧中，只见左右前后，到处都是铺天盖地的松树林。你似乎迷失了方向，像没头苍蝇般到处乱闯。]],["fightBackground"]=[[森林内]],["id"]=[[fb33_26]],["left"]=[[fb33_26]],["name"]=[[大松林]],["permission"]=2,["right"]=[[fb33_27]],["role1"]=[[fb33item19]],["role2"]=[[fb33item19]],["role3"]=[[fb33item19]],["role4"]=[[fb33item19]],["stepMusic"]=[[jiaobu]]},["fb33_27"]={["down"]=[[fb33_27]],["dsc"]=[[你眼前骤然一黑，朦胧中，只见左右前后，到处都是铺天盖地的松树林。你似乎迷失了方向，像没头苍蝇般到处乱闯。]],["fightBackground"]=[[森林内]],["id"]=[[fb33_27]],["item1"]=[[fb33item10]],["left"]=[[fb33_27]],["name"]=[[大松林]],["permission"]=2,["right"]=[[fb33_28]],["role1"]=[[f